@Test
void adoptsAnExactLegacySchemaAndAppliesOnlyLaterMigrations() throws Exception {
    var database = directory.resolve("legacy.db");
    try (var connection = DriverManager.getConnection("jdbc:sqlite:" + database)) {
        connection.createStatement().execute("CREATE TABLE baseline(value TEXT NOT NULL)");
        connection.createStatement().execute("INSERT INTO baseline VALUES ('preserved')");
    }
    LegacySchemaClassifier classifier = connection -> {
        try (var rows = connection.createStatement().executeQuery(
                "SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type='table' AND name='baseline')")) {
            return rows.getBoolean(1) ? 1 : 0;
        }
    };
    var manager = new SqliteMigrationManager(database, "legacy", List.of(
            new SqliteMigration(1, "baseline", List.of("CREATE TABLE baseline(value TEXT NOT NULL)")),
            new SqliteMigration(2, "later", List.of("CREATE TABLE later(id INTEGER PRIMARY KEY)"))), classifier);

    SqliteMigrationManager.Result result = manager.migrate();

    assertEquals(List.of(2), result.appliedVersions());
    assertTrue(result.backup().isPresent());
    try (var connection = DriverManager.getConnection("jdbc:sqlite:" + database)) {
        assertEquals(2, connection.createStatement().executeQuery("PRAGMA user_version").getInt(1));
        assertEquals("preserved", connection.createStatement().executeQuery("SELECT value FROM baseline").getString(1));
        assertTrue(connection.createStatement().executeQuery(
                "SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE name='later')").getBoolean(1));
    }
}

@Test
void refusesUnknownUnversionedSchemaWithoutChangingIt() throws Exception {
    var database = directory.resolve("unknown.db");
    try (var connection = DriverManager.getConnection("jdbc:sqlite:" + database)) {
        connection.createStatement().execute("CREATE TABLE unexpected(value TEXT)");
    }
    var manager = new SqliteMigrationManager(database, "unknown", List.of(
            new SqliteMigration(1, "baseline", List.of("CREATE TABLE expected(value TEXT)"))),
            connection -> -1);

    SqliteMigrationException failure = assertThrows(SqliteMigrationException.class, manager::migrate);

    assertEquals("storage.migration_failed", failure.code());
    try (var connection = DriverManager.getConnection("jdbc:sqlite:" + database)) {
        assertEquals(0, connection.createStatement().executeQuery("PRAGMA user_version").getInt(1));
        assertTrue(connection.createStatement().executeQuery(
                "SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE name='unexpected')").getBoolean(1));
        assertFalse(connection.createStatement().executeQuery(
                "SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE name='expected')").getBoolean(1));
    }
}

